using namespace std;

const int N = 2e5 + 8, N2 = N / 64 + 8;

int n, k, A, pts[N][3], buc[N], LW[N][2];
int cnt[N], pa[N2], Rp[N];
uint64_t mask[N2];

int find(int x) {
    return pa[x] < 0 ? x : pa[x] = find(pa[x]);
}

int main() {
    n = read(), k = read(), A = read();
    for (int i = 0; i < n; i++) {
        pts[i][1] = read();
        pts[i][0] = k - read();
        pts[i][2] = read();
        buc[pts[i][0]]++;
    }
    for (int i = 1; i <= k; i++) buc[i + 1] += buc[i];
    for (int i = 0; i < n; i++) {
        int t = --buc[pts[i][0]];
        memcpy(LW[t], pts[i] + 1, 8);
    }
    for (int i = 0; i < k; i++) cnt[i] = A;
    memset(mask, 0xff, sizeof mask);
    memset(pa, -1, sizeof pa);
    iota(Rp, Rp + N2, 0);
    int ans = 0;
    for (int r = 1; r <= k; r++)
        for (int i = buc[r]; i < buc[r + 1]; i++) {
            int l = LW[i][0], w = LW[i][1];
            ans += w;
            int lb = Rp[find(l >> 6)], rb = r >> 6;
            auto S0 = mask[lb];
            if (lb == l >> 6) S0 &= ~0ULL << (l & 63);
            while (lb < rb) {
                auto S = S0;
                for (; S; S &= S - 1) {
                    int p = lb * 64 + __builtin_ctzll(S);
                    int tmp = min(w, cnt[p]);
                    cnt[p] -= tmp, w -= tmp;
                    if (!w) break;
                }
                mask[lb] ^= S0 ^ S;
                if (!w) break;
                int nxt = find(lb + 1);
                if (!mask[lb]) {
                    lb = find(lb);
                    if (pa[nxt] > pa[lb]) swap(nxt, lb), Rp[nxt] = Rp[lb];
                    pa[nxt] += pa[lb], pa[lb] = nxt;
                }
                lb = Rp[nxt], S0 = mask[lb];
            }
            if (w != 0 & lb == rb) {
                S0 &= (1ULL << (r & 63)) - 1;
                auto S = S0;
                for (; S; S &= S - 1) {
                    int p = lb * 64 + __builtin_ctzll(S);
                    int tmp = min(w, cnt[p]);
                    cnt[p] -= tmp, w -= tmp;
                    if (!w) break;
                }
                mask[lb] ^= S0 ^ S;
            }
            ans -= w;
        }
    cout << ans << '\n';
}

